<script lang="ts">
 import {base} from '$app/paths';
 import {onMount} from 'svelte';
 import {replaceState} from '$app/navigation';
 import {catalog,styles,type Style,type Kind} from './catalog';
 import {initialReview,applyReview,type ReviewState,type ReviewChoice} from './review';
 import Component from './components/Component.svelte';import Piece from './components/Piece.svelte';import Token from './components/Token.svelte';
 const style:Style='moonlit';
 let kind=$state<Kind>('board'),context=$state<'public'|'private'>('public'),layout=$state('auto');
 let fixture=$state(initialReview()),history=$state<ReviewState[]>([]),message=$state('Board review: select a dot to inspect its paths, sightlines and sound distance. Move the Abbess only along connected dots.'),rejected=$state(false);
 let boardSelection=$state(26);
 let dialog:HTMLDialogElement;let inspectorOpen=$state(false);
 const selected=$derived(catalog.find(x=>x.id===kind)!);
 const groups=['Board','Pieces','Cards','Tokens','Player aids'];
 onMount(()=>{const p=new URLSearchParams(location.search);const component=p.get('component');if(catalog.some(c=>c.id===component))kind=component as Kind;});
 function sync(){const url=new URL(location.href);url.searchParams.delete('style');url.searchParams.delete('compare');url.searchParams.set('component',kind);historyReplace(url);}
 function historyReplace(url:URL){replaceState(url,{});}
 function selectKind(next:Kind){kind=next;sync();}
 function choose(choice:ReviewChoice){const result=applyReview(fixture,choice);rejected=!result.accepted;message=result.message;if(result.accepted){history=[...history,structuredClone($state.snapshot(fixture))];fixture=result.state;}}
 function undo(){if(!history.length)return;fixture=history[history.length-1];history=history.slice(0,-1);message='Undone. The complete previous review state is restored.';rejected=false;}
 function inspect(){inspectorOpen=true;dialog.showModal();}
</script>
<svelte:head><title>Nuns on the Run · Component workbench</title><meta name="description" content="Imagegen-painted board game components in Moonlit Storybook artwork. Shared renderers, live information overlays and reversible interaction fixtures."/></svelte:head>
<div class="workbench">
 <header class="workbench-header"><a href={base + '/'} class="wordmark">Nuns <i>on the</i> Run<span>COMPONENT WORKBENCH</span></a><span class="approved-direction">Moonlit Storybook <b>Approved art direction</b></span></header>
 <div class="workbench-body">
 <aside class="collection-nav"><div class="collection-label">THE COLLECTION <span>14</span></div><nav aria-label="Component collection">{#each groups as group}<div class="nav-group"><h2>{group}</h2>{#each catalog.filter(c=>c.category===group) as item}<button class:active={kind===item.id} aria-current={kind===item.id?'page':undefined} onclick={()=>selectKind(item.id)}>{item.name}<span>↗</span></button>{/each}</div>{/each}</nav><div class="art-origin"><span class="origin-dot"></span> Original imagegen artwork<p>Approved source paintings.<br/>Shared graphical layers.<br/>Live values stay editable.</p></div></aside>
 <main class="review-area">
 <div class="review-toolbar"><div class="mobile-collection"><label for="component-choice">Component</label><select id="component-choice" value={kind} onchange={e=>selectKind(e.currentTarget.value as Kind)}>{#each catalog as item}<option value={item.id}>{item.name}</option>{/each}</select></div><div class="component-title"><h1>{selected.name}</h1><span>{selected.category} <b>/</b> {kind==='board'?'Contextual table':selected.privacy}</span></div><div class="review-tools"><label class="layout-select">Layout<select aria-label="Review viewport" bind:value={layout}><option value="auto">This screen</option><option value="phone">390 px phone</option><option value="tablet">820 px tablet</option><option value="tabletop">Public table</option></select></label><button class="text-control" onclick={inspect}>Enlarge ↗</button></div></div>
 <div class="review-caption"><p>{kind==='board'?'Original numbered board, colored patrols, locks and objectives. Use the board audit to inspect sight and sound.':selected.note}</p><span>ART & INTERACTION REVIEW</span></div>
 <!-- svelte-ignore a11y_no_noninteractive_tabindex (The review surface is a keyboard-scrollable region.) -->
 <div class="review-scroll" role="region" aria-label="Component review surface" tabindex="0">
 <div class="review-canvas" class:phone-preview={layout==='phone'} class:tablet-preview={layout==='tablet'}>
 {#if kind==='board'}
 <div class="context-tabs" aria-label="Fixture information boundary"><button class:active={context==='public'||layout==='tabletop'} onclick={()=>context='public'}>Public table</button><button class:active={context==='private'&&layout!=='tabletop'} onclick={()=>{context='private';if(layout==='tabletop')layout='auto';}}>Private phone</button><span>{context==='public'||layout==='tabletop'?'Only sightings & clues':'Celeste’s sample view'}</span></div>
 <div class="table-scene" class:private-scene={context==='private'&&layout!=='tabletop'}>
 <div class="map-module"><Component audit kind="board" {style} state={fixture} onchoice={choose} inspectDot={boardSelection} oninspect={dot=>boardSelection=dot}/><div class="board-public-strip"><span><b>Round 6</b> / 15</span><span>Captures <b>2 / 4</b></span><span>Abbess · {fixture.guardDot} · {fixture.facing} →</span></div></div>
 <aside class="table-side"><h2>{context==='private'&&layout!=='tabletop'?'Your secret wish':'Abbess’s patrol'}</h2><Component audit kind={context==='private'&&layout!=='tabletop'?'wish':'patrol'} {style} state={fixture} onchoice={choose} inspectDot={boardSelection} oninspect={dot=>boardSelection=dot}/><div class="table-clues"><Token {style} kind="noise" label="Noise ↑"/><Token {style} kind="vanished" label="Vanished →"/></div></aside>
 <div class="table-cast"><div class="cast-heading"><h2>{context==='private'&&layout!=='tabletop'?'Your movement':'The abbey’s inhabitants'}</h2><span>{context==='private'&&layout!=='tabletop'?'PRIVATE · SAMPLE ONLY':'Character references · no hidden positions'}</span></div>{#if context==='private'&&layout!=='tabletop'}<Component audit kind="movement" {style} state={fixture} onchoice={choose} inspectDot={boardSelection} oninspect={dot=>boardSelection=dot}/>{:else}<div class="cast-row">{#each [0,1,2,3,4,5,6,7] as index}<Piece {style} {index}/>{/each}</div>{/if}</div>
 </div>
 {:else}<section class="object-review"><div class="component-stage"><Component audit {kind} {style} state={fixture} onchoice={choose} inspectDot={boardSelection} oninspect={dot=>boardSelection=dot}/></div><div class="context-help"><span class="small-caps">{styles[style].name}</span><h2>{kind==='movement'?'Choose a movement card.':kind==='key'?'Handle the actual pieces.':kind==='status'?'Capture updates status automatically.':'Painted objects. Live information.'}</h2><p>{kind==='movement'?'Touch a card to select it. Change the novice status to Caught, then try Run to review an explained rejection.':kind==='key'?'Touch the medicine before the key to see a rejected choice. Collect the key, then the medicine. Undo restores the complete previous fixture.':kind==='status'?'The caught fixture switches movement to Walk and returns medicine while retaining keys. Undo restores every dependent value.':'The same graphical component is used here and in enlarged review. Generated material and illustration stay separate from labels, quantities and selection.'}</p>{#if ['wish','blessing','patrol'].includes(kind)}<button class="plain-button" onclick={()=>choose({type:'reverse',card:kind})}>↻ {fixture.reversed[kind]?'Show face':'Show reverse'}</button>{/if}{#if kind==='movement' || kind==='status'}<button class="plain-button" onclick={()=>choose({type:'status'})}>↻ Set status: {fixture.caught?'On the run':'Caught'}</button><span class="fixture-state">Current status: {fixture.caught?'Caught':'On the run'}</span>{/if}<dl><div><dt>Minimum review size</dt><dd>{kind==='movement'?'260 px card width':['wish','blessing','patrol','backs'].includes(kind)?'320 px card width':kind==='die'?'200 px die model':kind==='novices'||kind==='guards'?'120 px visible figure height':'80 px token / 16 px values'}</dd></div><div><dt>Source</dt><dd>{kind==='die'?'Istanbul / Can’t Stop · Three.js renderer':'Imagegen · local layered assets'}</dd></div><div><dt>Scope</dt><dd>Presentation fixture, not a full game</dd></div></dl></div></section>{/if}
 </div></div>
 <div class="review-feedback" class:rejected role="status"><span class="feedback-icon">{rejected?'!':'↳'}</span><p>{message}</p><button class="undo-button" disabled={!history.length} onclick={undo}>↶ Undo <span>{history.length}</span></button></div>
 </main></div>
 <footer class="workbench-footer"><span>MOONLIT STORYBOOK / BOARD AUDIT</span><span>Fréderic Moyersoen · Independent digital adaptation · Original 2010 board geometry</span><a href={base + '/lab/'}>Animation lab ↗</a><a href={base + '/art/manifest.json'} target="_blank" rel="noreferrer">Asset manifest ↗</a></footer>
</div>
<dialog bind:this={dialog} onclose={()=>inspectorOpen=false} class="component-inspector"><header><div><span class="small-caps">SHARED COMPONENT · {style}</span><h2>{selected.name}</h2></div><button class="plain-button" onclick={()=>dialog.close()}>Return to collection ✕</button></header>{#if inspectorOpen}<div class="inspector-stage"><Component audit {kind} {style} state={fixture} onchoice={choose} inspectDot={boardSelection} oninspect={dot=>boardSelection=dot}/></div>{/if}<div class="inspector-footer"><p>{selected.note}</p><button class="undo-button" disabled={!history.length} onclick={undo}>↶ Undo</button></div><div class="inspector-feedback" role="status">{message}</div></dialog>
